 type Sweep={id:string;name:string;sweepId:string;datasetViewId?:string}; type StrategyJob={id:string;operation:'validate'|'run'|'rank'|'lua-validate'|'lua-run';sweepId:string;status:'queued'|'running'|'complete'|'failed'|'cancelled';createdAt:string;updatedAt:string;progress?:unknown;result?:unknown;error?:string;metric?:string}; type StrategyCatalog={sweeps:Sweep[];jobs:StrategyJob[]};
 let chartEl:HTMLDivElement; let chart:IChartApi|undefined; let candleSeries:any; let chartSource=''; let raw:Candle[]=[]; let chartTimestampLabels=new Map<number,string>(); let csvName=''; let csvError=''; let symbol='—'; let timeframe='5 min'; let barType='Time bars'; let strategy='EMA crossover'; let source='Upload CSV'; let saved:Saved[]=[]; let configName='Untitled workspace'; let toast=''; let showSaved=false; let heikin=false;
 let catalog:Dataset[]=[]; let catalogWarnings:string[]=[]; let catalogError=''; let catalogRequest=0; let cacheLoading=false; let cacheError=''; let cacheStatus=''; let cacheDatasetId=''; let cacheSeriesKey=''; let rawBarValue=1; let cachePageCount=0; let cacheTotal=0; let restoredWithoutData=false; let cacheRequest=0;
 let sweeps:Sweep[]=[]; let strategyJobs:StrategyJob[]=[]; let strategyError=''; let strategyLoading=false; let strategySweepId=''; let strategySearch=''; let strategyMetric='robustness'; let selectedRunJobId=''; let selectedHistoryJobId=''; let strategyBusy=false; let strategyActionError=''; let strategyPoll=0;
 type LiveBar={ts_ns:string;open:number;high:number;low:number;close:number;volume?:number}; type ProviderSnapshot={connection_status:string;chart_freshness:string;contract:string;bar_kind:string;bar_value:number;bars:LiveBar[];fidelity:string;broker_source:string;observed_at:string|null;latest_bar_ts_ns:string|null}; let providerBars:LiveBar[]=[]; let providerError=''; let providerMeta=''; let providerStatus='ended'; let liveBars:LiveBar[]=[]; let liveError=''; let liveStatus='disconnected'; let liveUpdatedAt=0; let liveNow=Date.now(); let livePoll=0; let liveBusy=false; const liveEpoch=new RequestEpoch(); let liveAbort:AbortController|undefined;
 const rankMetrics=['robustness','net-pnl','gross-pnl','fees','max-drawdown','required-account-size','return-required','profit-factor','win-rate','trade-count','average-trade','average-giveback','largest-giveback','mfe-capture'];
 $: activeJob=strategyJobs.find(x=>x.status==='queued'||x.status==='running');
 $: latestJob=[...strategyJobs].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];
