 $: completedRuns=strategyJobs.filter(x=>x.operation==='run'&&x.status==='complete'&&x.sweepId===selectedSweep?.sweepId).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
 $: if(completedRuns.length&&!completedRuns.some(x=>x.id===selectedRunJobId)) selectedRunJobId=completedRuns[0].id;
