 $: activeSeries=selectedDataset()?.series.find(x=>seriesKey(x)===cacheSeriesKey);
 const epoch=(v:string):number|null=>{const n=Number(v);if(Number.isFinite(n)&&n>0&&n<1e10)return Math.floor(n);const d=Date.parse(v);return Number.isNaN(d)?null:Math.floor(d/1000)};
 $: candles=source==='Live engine'?liveBars.map((b,i)=>({time:i as UTCTimestamp,open:b.open,high:b.high,low:b.low,close:b.close})):source==='Provider snapshot'?providerBars.map((b,i)=>({time:i as UTCTimestamp,open:b.open,high:b.high,low:b.low,close:b.close})):heikin?raw.reduce<Candle[]>((out,c)=>{const close=(c.open+c.high+c.low+c.close)/4;const previous=out[out.length-1];const open=previous?(previous.open+previous.close)/2:(c.open+c.close)/2;out.push({time:c.time,open,close,high:Math.max(c.high,open,close),low:Math.min(c.low,open,close)});return out},[]):raw;
 $: liveStale=!liveUpdatedAt||liveNow-liveUpdatedAt>15_000;
 function nsLabel(value:string){const ns=BigInt(value);if(ns<0n)return value;const seconds=ns/1_000_000_000n;if(seconds>8_640_000_000_000n)return value;return new Date(Number(seconds)*1000).toISOString().slice(0,19)+'.'+String(ns%1_000_000_000n).padStart(9,'0')+'Z'}
 function showProviderSnapshot(event:CustomEvent<ProviderSnapshot>){if(source!=='Provider snapshot')return;const snap=event.detail;providerBars=providerSnapshotBars(snap.bars);const labels=new Map<number,string>();providerBars.forEach((b,i)=>labels.set(i,nsLabel(b.ts_ns)));chartTimestampLabels=labels;providerError='';providerStatus='connected';providerMeta=`${snap.broker_source} · ${snap.fidelity} · freshness unknown${snap.observed_at?` · observed ${snap.observed_at}`:''} · latest ns ${snap.latest_bar_ts_ns??providerBars.at(-1)?.ts_ns??'not reported'}`;symbol=snap.contract;timeframe=`${snap.bar_value} ${snap.bar_kind} · provider stream`;barType=`Provider ${snap.bar_kind} bars`}
 function showProviderState(event:CustomEvent<{status:string;error?:string}>){providerStatus=event.detail.status;providerError=event.detail.error??''}
 function invalidateLive(){liveEpoch.invalidate();liveAbort?.abort();liveAbort=undefined;liveBusy=false}
 async function refreshLive(){if(source!=='Live engine'||liveBusy)return;const generation=liveEpoch.capture();liveBusy=true;const controller=new AbortController();liveAbort=controller;const timeout=window.setTimeout(()=>controller.abort(),3500);try{const response=await fetch('/api/live-market',{cache:'no-store',signal:controller.signal});const body=await response.json();if(!liveEpoch.isCurrent(generation)||source!=='Live engine')return;if(!response.ok)throw new Error(typeof body.error==='string'?body.error:`Live market request failed (${response.status}).`);if(body.source!=='engine_market_snapshot'||!Array.isArray(body.bars))throw new Error('The live market API returned an invalid snapshot.');const next:LiveBar[]=[];const labels=new Map<number,string>();for(const b of body.bars){if(typeof b.ts_ns!=='string'||! /^-?\d+$/.test(b.ts_ns)||![b.open,b.high,b.low,b.close].every(Number.isFinite)||b.high<b.low)throw new Error('The engine snapshot contains an invalid bar.');labels.set(next.length,nsLabel(b.ts_ns));next.push(b)}liveBars=next;chartTimestampLabels=labels;liveStatus='connected';liveError='';liveUpdatedAt=Date.now();liveNow=liveUpdatedAt;symbol=body.contract??'Live engine market';timeframe='Live engine snapshot';barType='Engine market bars'}catch(e){if(liveEpoch.isCurrent(generation)&&source==='Live engine'){liveStatus='disconnected';liveError=e instanceof Error?e.message:'Unable to read live market data.'}}finally{window.clearTimeout(timeout);if(liveEpoch.isCurrent(generation)){if(liveAbort===controller)liveAbort=undefined;liveBusy=false}}}
 function chooseLive(){invalidateLive();cacheRequest++;cacheLoading=false;raw=[];liveBars=[];liveError='';liveUpdatedAt=0;source='Live engine';void refreshLive()}
 function ingest(file:File){chartTimestampLabels=new Map();cacheRequest++;cacheLoading=false;restoredWithoutData=false;source='Upload CSV';cacheStatus='';cacheError='';csvError='';csvName=file.name;Papa.parse<Record<string,string>>(file,{header:true,skipEmptyLines:true,complete:({data,meta})=>{const hs=meta.fields??[];const col=(names:string[])=>hs.find(x=>names.includes(x.trim().toLowerCase()));const t=col(['time','timestamp','datetime','date']),o=col(['open']),h=col(['high']),l=col(['low']),c=col(['close']);if(!t||!o||!h||!l||!c){csvError='CSV needs timestamp/date plus open, high, low and close columns.';raw=[];return}const rows=new Map<number,Candle>();let duplicates=0;for(const r of data){const time=epoch(r[t]??''),open=Number(r[o]),high=Number(r[h]),low=Number(r[l]),close=Number(r[c]);if(time===null||![open,high,low,close].every(Number.isFinite)||high<low)continue;if(rows.has(time)){duplicates++;continue}rows.set(time,{time:time as UTCTimestamp,open,high,low,close})}raw=[...rows.values()].sort((a,b)=>Number(a.time)-Number(b.time));if(duplicates){raw=[];csvError=`${duplicates} CSV row${duplicates===1?'':'s'} share a chart timestamp. The chart requires unique second-level timestamps, so this file was not charted.`}else if(!raw.length)csvError='No valid OHLC rows found in this file.';else symbol=file.name.replace(/\.[^.]+$/,'').toUpperCase()},error:e=>csvError=e.message})}
 async function readJson<T>(response:Response):Promise<T>{const body=await response.text();let parsed:unknown;try{parsed=JSON.parse(body)}catch{throw new Error('The chart cache bridge returned invalid JSON.')}if(!response.ok){const message=(parsed as {error?:unknown})?.error;throw new Error(typeof message==='string'?message:`Chart cache request failed (${response.status}).`)}return parsed as T}
 async function readStrategyJson<T>(response:Response):Promise<T>{const body=await response.text();let parsed:unknown;try{parsed=JSON.parse(body)}catch{throw new Error('The local strategy API returned invalid JSON.')}if(!response.ok){const message=(parsed as {error?:unknown})?.error;throw new Error(typeof message==='string'?message:`Strategy request failed (${response.status}).`)}return parsed as T}
 async function refreshStrategy(){strategyLoading=true;try{const result=await readStrategyJson<StrategyCatalog>(await fetch('/api/strategy',{cache:'no-store'}));sweeps=result.sweeps??[];strategyJobs=result.jobs??[];if(!sweeps.some(x=>x.id===strategySweepId))strategySweepId=sweeps[0]?.id??'';strategyError=''}catch(e){strategyError=e instanceof Error?e.message:'Unable to read native sweep specs.'}finally{strategyLoading=false}}
 async function submitStrategy(operation:'validate'|'run'|'rank'){strategyActionError='';if(!strategySweepId){strategyActionError='Select an existing native sweep spec first.';return}const source=selectedRun;if(operation==='rank'&&!source){strategyActionError='Ranking requires a completed replay from this sweep.';return}strategyBusy=true;try{const body={operation,sweepId:strategySweepId,...(operation==='rank'?{sourceJobId:source!.id,metric:strategyMetric}:{})};const job=await readStrategyJson<StrategyJob>(await fetch('/api/strategy',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}));strategyJobs=[job,...strategyJobs.filter(x=>x.id!==job.id)]}catch(e){strategyActionError=e instanceof Error?e.message:'Unable to submit native strategy job.'}finally{strategyBusy=false}}
 async function pollStrategy(){const current=activeJob;if(!current)return;try{const job=await readStrategyJson<StrategyJob>(await fetch(`/api/strategy/jobs/${encodeURIComponent(current.id)}`,{cache:'no-store'}));strategyJobs=[job,...strategyJobs.filter(x=>x.id!==job.id)]}catch(e){strategyActionError=e instanceof Error?e.message:'Unable to read strategy job status.'}}
 async function cancelStrategy(){const current=activeJob;if(!current)return;strategyBusy=true;strategyActionError='';try{const job=await readStrategyJson<StrategyJob>(await fetch(`/api/strategy/jobs/${encodeURIComponent(current.id)}`,{method:'DELETE'}));strategyJobs=[job,...strategyJobs.filter(x=>x.id!==job.id)]}catch(e){strategyActionError=e instanceof Error?e.message:'Unable to cancel strategy job.'}finally{strategyBusy=false}}
 async function discoverCache(){const requestId=++catalogRequest;catalogError='';try{const response=await fetchStoredCachePage(fetch,'/api/chart-cache',()=>requestId===catalogRequest);if(requestId!==catalogRequest||!response)return;const result=await readJson<Catalog>(response);if(requestId!==catalogRequest)return;catalog=result.datasets??[];catalogWarnings=result.warnings??[];if(!catalog.some(d=>d.id===cacheDatasetId)){cacheDatasetId=catalog[0]?.id??''}syncSeries()}catch(e){if(requestId===catalogRequest){catalog=[];catalogError=e instanceof Error?e.message:'Unable to read stored chart datasets.'}}}
 function syncSeries(){const d=selectedDataset();if(!d){cacheSeriesKey='';return}if(!d.series.some(x=>seriesKey(x)===cacheSeriesKey))cacheSeriesKey=d.series[0]?seriesKey(d.series[0]):''}
 function datasetChanged(){syncSeries();const selected=activeSeries;if(selected)rawBarValue=selected.bar_type.value;void loadCache()}
 function seriesChanged(){const selected=activeSeries;if(selected)rawBarValue=selected.bar_type.value;void loadCache()}
 function rawValueChanged(){void loadCache()}
 async function selectCacheSource(){invalidateLive();const requestId=++cacheRequest;raw=[];cacheError='';cacheStatus='';restoredWithoutData=false;await discoverCache();if(requestId===cacheRequest&&source==='Stored cache'&&cacheDatasetId)await loadCache()}
 async function loadCache(){const requestId=++cacheRequest;const d=selectedDataset(),s=d?.series.find(x=>seriesKey(x)===cacheSeriesKey);if(!d||!s){raw=[];cacheLoading=false;return}const requestedValue=s.input==='raw_ticks'?rawBarValue:s.bar_type.value;if(!Number.isInteger(requestedValue)||requestedValue<1||requestedValue>1_000_000){raw=[];cacheError='Raw bar value must be a whole number from 1 to 1,000,000.';cacheLoading=false;return}restoredWithoutData=false;source='Stored cache';cacheLoading=true;cacheError='';csvError='';csvName='';cacheStatus='';raw=[];cachePageCount=0;cacheTotal=0;try{const kind=s.bar_type.kind;const params=new URLSearchParams({input:s.input==='raw_ticks'?'raw-ticks':'server-bars',bar_kind:kind,bar_value:String(requestedValue),chart_mode:s.candle_mode==='standard'?'ohlc':'heikin-ashi',offset:'0',limit:'5000'});let offset=0;const bars:Candle[]=[];const timestampLabels=new Map<number,string>();let lastTimestampNs:bigint|undefined;let expectedTotal:number|undefined;const maxBars=50_000;while(expectedTotal===undefined||offset<expectedTotal){params.set('offset',String(offset));const url=`/api/chart-cache/${encodeURIComponent(d.id)}?${params}`;const response=await fetchStoredCachePage(fetch,url,()=>requestId===cacheRequest);if(requestId!==cacheRequest)return;if(!response) return;const body=await response.text();let page:CachePage;try{page=JSON.parse(body) as CachePage}catch{throw new Error('The chart cache bridge returned invalid JSON.')}if(!response.ok){const message=(page as unknown as {error?:unknown}).error;throw new Error(typeof message==='string'?message:`Chart cache request failed (${response.status}).`)}const responseSeries=page.series;const matchesRequestedSeries=responseSeries?.input===s.input&&responseSeries.bar_type.kind===kind&&responseSeries.bar_type.value===requestedValue&&responseSeries.candle_mode===s.candle_mode;if(page.dataset_id!==d.id||page.source_status!==(s.input==='raw_ticks'?'stored_raw_ticks':'stored_cache')||!matchesRequestedSeries)throw new Error('The response did not confirm the selected stored-cache dataset provenance and requested series.');if(page.total<0||page.bars.length>5000)throw new Error('The chart cache page contains invalid pagination metadata.');if(expectedTotal===undefined){expectedTotal=page.total;if(expectedTotal>maxBars)throw new Error(`This series contains ${expectedTotal.toLocaleString()} bars. Automatic chart loading is limited to ${maxBars.toLocaleString()} bars; choose a smaller series when one is available.`)}if(page.total!==expectedTotal||page.offset!==offset||!page.bars.length&&offset<expectedTotal)throw new Error('The chart cache returned inconsistent pages.');
 for(let i=0;i<page.bars.length;i++){const rawNs=page.bars[i].timestamp_ns;if(typeof rawNs!=='string'||! /^-?\d+$/.test(rawNs))throw new Error('The chart cache returned a timestamp without the exact string contract.');const ns=BigInt(rawNs);const seconds=ns/1_000_000_000n;if(ns<0n||seconds>BigInt(Number.MAX_SAFE_INTEGER)||seconds<BigInt(Number.MIN_SAFE_INTEGER))throw new Error('A stored timestamp is outside the chart’s supported UTC range.');if(lastTimestampNs!==undefined&&ns<lastTimestampNs)throw new Error('Stored bars are not in timestamp order.');lastTimestampNs=ns;const index=bars.length;const {open,high,low,close}=page.bars[i];if(![open,high,low,close].every(Number.isFinite)||high<low)throw new Error('A stored bar contains invalid OHLC values.');const iso=new Date(Number(seconds)*1000).toISOString().slice(0,19)+'.'+String(ns%1_000_000_000n).padStart(9,'0')+'Z';timestampLabels.set(index,iso);bars.push({time:index as UTCTimestamp,open,high,low,close})}offset+=page.bars.length;cachePageCount++;cacheTotal=expectedTotal}
 if(requestId!==cacheRequest)return;chartTimestampLabels=timestampLabels;raw=bars;symbol=d.instrument.symbol??d.display_name;timeframe=`${s.input==='raw_ticks'?'Raw ticks':'Server bars'} · ${requestedValue} ${kind}${requestedValue===1?'':'s'} · ${s.candle_mode==='standard'?'OHLC':'Heikin Ashi'}`;barType=`${kind} bars`;heikin=false;cacheStatus=`${s.input==='raw_ticks'?'Stored raw ticks':'Stored server bars'} · ${d.provider} ${d.environment} · ${cachePageCount} page${cachePageCount===1?'':'s'} · ${bars.length.toLocaleString()} of ${cacheTotal.toLocaleString()} bars · equal spacing by bar sequence; labels show original UTC timestamp`;if(!bars.length)cacheStatus+=' · no bars in this series'}catch(e){if(requestId===cacheRequest){raw=[];cacheError=e instanceof Error?e.message:'Unable to load stored bars.'}}finally{if(requestId===cacheRequest)cacheLoading=false}}
 function draw(){if(!chartEl)return;if(!candles.length){chart?.remove();chart=undefined;candleSeries=undefined;chartSource='';return;}if(chart&&chartSource===source&&candleSeries){candleSeries.setData(candles);return;}chart?.remove();chart=undefined;candleSeries=undefined;chartSource=source;const stored=(source==='Stored cache'||source==='Live engine'||source==='Provider snapshot')&&chartTimestampLabels.size>0;const labels=[...chartTimestampLabels.values()];const years=new Set(labels.map(label=>label.slice(0,4)));const minuteCounts=new Map<string,number>();for(const label of labels){const minute=label.slice(0,16);minuteCounts.set(minute,(minuteCounts.get(minute)??0)+1)}const showYear=years.size>1;const showSeconds=labels.some(label=>label.slice(17,19)!=='00'||label.slice(20,29)!=='000000000')||[...minuteCounts.values()].some(count=>count>1);const axisTimeLabel=(label:string)=>`${showYear?label.slice(0,10):label.slice(5,10)} ${label.slice(11,16)}${showSeconds?`:${label.slice(17,19)}`:''}`;const behavior=new (defaultHorzScaleBehavior())();chart=createChartEx(chartEl,behavior,({autoSize:true,layout:{background:{type:ColorType.Solid,color:'#f8f6f0'},textColor:'#817b6f',fontFamily:'Inter, sans-serif'},grid:{vertLines:{color:'#efede6'},horzLines:{color:'#efede6'}},rightPriceScale:{borderColor:'#e5e1d7'},timeScale:{borderColor:'#e5e1d7',timeVisible:true,tickMarkFormatter:(time:any)=>{if(!stored)return null;const exact=chartTimestampLabels.get(Number(time));return exact?axisTimeLabel(exact):String(time)}},localization:{timeFormatter:(time:any)=>stored?(chartTimestampLabels.get(Number(time))??String(time)):new Date(Number(time)*1000).toISOString()},crosshair:{vertLine:{color:'#bf984b',labelBackgroundColor:'#836629'},horzLine:{color:'#bf984b',labelBackgroundColor:'#836629'}}} as any)) as IChartApi;candleSeries=chart.addSeries(CandlestickSeries,{upColor:'#648471',downColor:'#bc7461',borderUpColor:'#648471',borderDownColor:'#bc7461',wickUpColor:'#648471',wickDownColor:'#bc7461'});candleSeries.setData(candles);chart.timeScale().fitContent()}
 function loadFile(e:Event){const f=(e.currentTarget as HTMLInputElement).files?.[0];if(f)ingest(f)}
 function save(){saved=[{id:Date.now(),name:configName.trim()||'Untitled workspace',symbol,timeframe,barType,strategy,ha:heikin,updated:new Date().toLocaleDateString()},...saved];localStorage.setItem('midas-research-configs',JSON.stringify(saved));toast='Workspace saved on this device';setTimeout(()=>toast='',2200)}
 function restore(x:Saved){invalidateLive();source='Upload CSV';liveBars=[];liveError='';liveUpdatedAt=0;chartTimestampLabels=new Map();cacheRequest++;cacheLoading=false;configName=x.name;symbol=x.symbol;timeframe=x.timeframe;barType=x.barType;strategy=x.strategy;heikin=x.ha;raw=[];csvName='';cacheStatus='';cacheError='';restoredWithoutData=true;toast='Loaded settings; data must be selected again';setTimeout(()=>toast='',2600)}
 function removeSaved(id:number){saved=saved.filter(x=>x.id!==id);localStorage.setItem('midas-research-configs',JSON.stringify(saved))}
 onMount(()=>{try{saved=JSON.parse(localStorage.getItem('midas-research-configs')||'[]')}catch{saved=[]}void discoverCache();void refreshStrategy();strategyPoll=window.setInterval(()=>{void pollStrategy();if(!activeJob)void refreshStrategy()},1300);livePoll=window.setInterval(()=>{liveNow=Date.now();if(source==='Live engine')void refreshLive()},2000);const ro=new ResizeObserver(()=>chart?.applyOptions({}));if(chartEl)ro.observe(chartEl);return()=>{window.clearInterval(strategyPoll);window.clearInterval(livePoll);invalidateLive();ro.disconnect();chart?.remove()}}); $: if(chartEl && candles) draw();
</script>
