<div class="shell"><aside class="rail"><a class="brand" href="/" aria-label="Midas home"><span class="brand-mark">M</span><span>MIDAS</span></a><div class="rail-links"><a class="rail-link active" href="#workspace" aria-label="Workspace"><LineChart size={19}/></a><a class="rail-link" href="#market-setup" aria-label="Market setup"><Database size={19}/></a><a class="rail-link" href="#sweep-editor" aria-label="Sweep editor"><Layers3 size={19}/></a></div><div class="rail-bottom"><div class="avatar">MN</div></div></aside><main class="main" id="workspace"><header class="topbar"><div class="crumb">Research <span>/</span> <b>Workspace</b></div><div class="top-actions"><span class="backend"><i></i> Local workspace</span><div class="avatar small">MN</div></div></header><div class="content">
<section class="heading"><div><div class="eyebrow"><Sparkles size={13}/> MARKET RESEARCH</div><h1>Trading workspace</h1><p>Shape your market view, configure a strategy and prepare a backtest.</p></div><button class="btn secondary" onclick={()=>showSaved=!showSaved}><Bookmark size={15}/> Saved workspaces <span class="count">{saved.length}</span></button></section>
{#if showSaved}<section class="saved"><div class="saved-head"><div><b>Saved workspaces</b><p>Stored in this browser on this device.</p></div><button class="icon" aria-label="Close" onclick={()=>showSaved=false}>×</button></div>{#if !saved.length}<div class="empty-saved">No saved workspaces yet. Save this setup to return later.</div>{:else}{#each saved as x}<div class="saved-item"><button class="saved-name" onclick={()=>restore(x)}><b>{x.name}</b><span>{x.symbol} · {x.timeframe} · {x.strategy}</span></button><small>{x.updated}</small><button class="icon" aria-label="Delete saved workspace" onclick={()=>removeSaved(x.id)}><Trash2 size={15}/></button></div>{/each}{/if}</section>{/if}
<div class="grid"><section class="panel chart-panel"><div class="chart-head"><div><div class="kicker">MARKET VIEW</div><div class="instrument"><strong>{symbol==='—'?'No instrument selected':symbol}</strong><span class="pill">{source==='Live engine'?(liveBars.length?liveBars.length.toLocaleString()+' bars':liveBusy?'Connecting…':'Awaiting live data'):source==='Provider snapshot'?(providerBars.length?providerBars.length.toLocaleString()+' bars':'Awaiting provider snapshot'):raw.length?raw.length.toLocaleString()+' bars':cacheLoading?'Loading…':'Awaiting data'}</span></div></div><div class="chart-tools">{#if source==='Live engine'}<button class="btn secondary" onclick={()=>void refreshLive()} disabled={liveBusy}><RefreshCw size={13}/> Refresh</button>{/if}<label class="select-wrap" title="Series shown from selected data"><Clock3 size={14}/><span>{timeframe}</span></label></div></div><div class="chart-meta"><i class:offline={source==='Live engine'&&liveStatus!=='connected'}></i><b>{source==='Live engine'?`Live engine · ${liveStatus}`:source==='Provider snapshot'?`Provider stream · ${providerStatus}`:barType}</b><span>·</span>{source==='Provider snapshot'?`${providerMeta}${providerError?` · ${providerError}`:''}`:source==='Live engine'?`Broker: not reported · Chart freshness: unknown · ${liveUpdatedAt?`Observer updated ${Math.max(0,Math.floor((liveNow-liveUpdatedAt)/1000))}s ago${liveStale?' · stale':''}`:'No successful observer response'}${liveError?` · ${liveError}`:''}`:source==='Stored cache'?cacheStatus||'Stored cache series':csvName||'Upload OHLC data to inspect bars'}</div><div class="chart-stage" bind:this={chartEl}>{#if source==='Live engine'?!liveBars.length:source==='Provider snapshot'?!providerBars.length:!raw.length}<div class="chart-empty"><div class="empty-icon"><BarChart3 size={23}/></div><strong>{source==='Live engine'?(liveBusy?'Connecting to engine…':liveError?'Live market unavailable':'Waiting for engine market snapshot'):source==='Provider snapshot'?providerStatus==='connecting'?'Connecting to provider…':providerError?'Provider market unavailable':'Start the provider stream':cacheLoading?'Loading stored bars…':cacheError?'Stored bars unavailable':restoredWithoutData?'Workspace settings restored':'Your chart will appear here'}</strong><span>{source==='Provider snapshot'?'Use Start stream in the provider panel. Provider authentication occurs only after that explicit request.':source==='Live engine'?(liveError||'The observer reads the already subscribed engine market snapshot. It sends no commands and does not simulate data.'):cacheError||csvError||(restoredWithoutData?'Saved workspaces keep settings only. Select a data source and dataset or reload the CSV.':source==='Stored cache'?'Choose an available stored dataset and series. No sample market data is shown.':'Upload your own OHLC data. No sample market data is shown.')}</span>{#if source==='Upload CSV'}<label class="btn upload"><Upload size={15}/> Choose CSV<input type="file" accept=".csv,text/csv" onchange={loadFile}/></label>{/if}</div>{/if}</div><div class="chart-foot"><span><i></i>{source==='Provider snapshot'?(providerBars.length?`Provider stream · ${providerStatus} · freshness unknown`:`Provider stream ${providerStatus}`):source==='Live engine'?(liveBars.length?`Engine snapshot · ${liveStale?'stale':'observer current'} · broker freshness unknown`:liveStatus==='connected'?'Engine connected · no bars in snapshot':'Engine disconnected'):raw.length?(source==='Stored cache'?'Stored cache bars':'CSV loaded locally'):cacheLoading?'Reading stored cache':cacheError?'Stored cache error':'No bars loaded'}</span><span><a href="https://www.tradingview.com/" target="_blank" rel="noreferrer">Lightweight Charts™ by TradingView</a></span></div></section>
<aside class="panel setup" id="market-setup"><div class="panel-title"><div><div class="kicker">CONFIGURATION</div><h2>Market setup</h2></div></div><div class="label">Data source</div><div class="select-box"><Database size={15}/><select bind:value={source} aria-label="Data source" onchange={()=>{if(source!=='Stored cache')catalogRequest++;if(source==='Live engine')chooseLive();else if(source==='Stored cache')void selectCacheSource();else if(source==='Provider snapshot'){invalidateLive();cacheRequest++;raw=[];liveBars=[];providerBars=[];providerError='';providerStatus='ended';}else{invalidateLive();cacheRequest++;cacheLoading=false;raw=[];liveBars=[];cacheError='';cacheStatus='';restoredWithoutData=false}}}><option>Upload CSV</option><option>Stored cache</option><option>Live engine</option><option>Provider snapshot</option></select><ChevronDown size={13}/></div>{#if source==='Upload CSV'}<label class="drop"><FileUp size={18}/><span><b>{csvName||'Choose a local CSV file'}</b><small>Timestamp and OHLC columns</small></span><input type="file" accept=".csv,text/csv" onchange={loadFile}/></label>{:else if source==='Stored cache'}<div class="cache-controls"><div class="label">Stored dataset</div><div class="select-box"><select bind:value={cacheDatasetId} aria-label="Stored dataset" disabled={cacheLoading||!catalog.length} onchange={datasetChanged}><option value="">{catalogError?'Catalog unavailable':catalog.length?'Choose a dataset':'No stored datasets found'}</option>{#each catalog as d}<option value={d.id}>{d.display_name} · {d.instrument.symbol??d.instrument.name??'Instrument'} · {d.source_status}</option>{/each}</select><ChevronDown size={13}/></div>{#if selectedDataset()}<div class="label series-label">Available series</div><div class="select-box"><select bind:value={cacheSeriesKey} aria-label="Available stored series" disabled={cacheLoading} onchange={seriesChanged}>{#each selectedDataset()?.series??[] as item}<option value={seriesKey(item)}>{seriesLabel(item)}</option>{/each}</select><ChevronDown size={13}/></div>{#if activeSeries?.input==='raw_ticks'}<div class="label">Raw bar value</div><div class="select-box"><input class="raw-value" type="number" min="1" max="1000000" step="1" bind:value={rawBarValue} aria-label="Raw bar value" disabled={cacheLoading} onchange={rawValueChanged}/></div><small class="cache-message">Whole number from 1 to 1,000,000</small>{/if}{/if}{#if cacheLoading}<small class="cache-message">Loading pages from stored cache…</small>{/if}{#if cacheError}<small class="error">{cacheError}</small>{/if}{#if catalogError}<small class="error">{catalogError}</small>{/if}{#if catalogWarnings.length}<small class="cache-message">{catalogWarnings.length} cache catalog warning{catalogWarnings.length===1?'':'s'}.</small>{/if}</div>{:else if source==='Provider snapshot'}<StandaloneMarketSource on:snapshot={showProviderSnapshot} on:state={showProviderState}/>{:else}<div class="note"><Activity size={14}/><span>Reads the currently subscribed engine chart. Broker identity and chart freshness are not reported by the engine.</span></div>{/if}<div class="field-row"><div><div class="label">Bar series</div><div class="select-box"><span>{source==='Live engine'?'Engine subscribed series':source==='Provider snapshot'?providerBars.length?`${providerBars.length} provider bars`:'No provider bars':source==='Stored cache'?(activeSeries?seriesLabel(activeSeries,activeSeries.input==='raw_ticks'?rawBarValue:activeSeries.bar_type.value):'Select a series'):csvName?'CSV time bars':'No CSV bars loaded'}</span></div></div><div><div class="label">Price transform</div><div class="select-box"><select bind:value={heikin} aria-label="Price transform" disabled={source!=='Upload CSV'}><option value={false}>Standard OHLC</option><option value={true}>Heikin Ashi</option></select><ChevronDown size={13}/></div></div></div><div class="ha-note">{source==='Live engine'?'The engine controls the current bar series and price transform.':source==='Stored cache'?'Stored series use the exact OHLC or Heikin Ashi variant listed above.':'Heikin Ashi is a chart-only transform of uploaded bars.'}</div><div class="divider"></div><div class="kicker">NATIVE REPLAY SPECS</div><div class="note"><Activity size={14}/><span>Only existing native JSON sweep specs are listed. Runs use the selected spec’s dataset and local offline replay; uploaded chart data is not passed to the strategy engine.</span></div>{#if strategyError}<small class="error">{strategyError}</small>{/if}<div class="label">Existing sweep spec · {sweeps.length.toLocaleString()} available</div><input class="strategy-search" type="search" bind:value={strategySearch} placeholder="Search name, sweep ID, or dataset…" aria-label="Search native sweep specs" disabled={strategyLoading||!sweeps.length||!!activeJob}/><small class="cache-message">{filteredSweeps.length.toLocaleString()} matches{filteredSweeps.length>100?' · showing first 100; refine search':''}</small><div class="select-box"><select bind:value={strategySweepId} aria-label="Existing native sweep spec" disabled={strategyLoading||!sweeps.length||!!activeJob}><option value="">{strategyLoading?'Loading native specs…':sweeps.length?'Select an existing sweep spec':'No supported native specs found'}</option>{#each visibleSweeps as item (item.id)}<option value={item.id}>{item.name} · {item.sweepId}{item.id===strategySweepId&&!filteredSweeps.some(x=>x.id===item.id)&&searchNeedle?' · current selection':''}</option>{/each}</select><ChevronDown size={13}/></div>{#if selectedSweep}<small class="cache-message">Dataset view: {selectedSweep.datasetViewId??'not reported'}</small>{/if}<div class="strategy-actions"><button class="btn secondary" onclick={()=>submitStrategy('validate')} disabled={strategyBusy||!!activeJob||!strategySweepId}><Activity size={14}/> Validate</button><button class="btn primary" onclick={()=>submitStrategy('run')} disabled={strategyBusy||!!activeJob||!strategySweepId}><Play size={14} fill="currentColor"/> Run replay</button></div>{#if activeJob}<div class="strategy-status"><div><b>{activeJob?.operation==='run'||activeJob?.operation==='lua-run'?'Replay':activeJob?.operation==='validate'||activeJob?.operation==='lua-validate'?'Validation':'Ranking'} {activeJob?.status}</b><button class="btn danger" onclick={cancelStrategy} disabled={strategyBusy}>Cancel</button></div><ReplayJobProgress progress={activeJob.progress} jobStatus={activeJob.status} jobError={activeJob.error}/></div>{/if}{#if strategyActionError}<small class="error">{strategyActionError}</small>{/if}{#if selectedRun}<div class="label">Completed run · {completedRuns.length.toLocaleString()} available</div><div class="select-box"><select bind:value={selectedRunJobId} aria-label="Completed strategy run">{#each completedRuns as run (run.id)}<option value={run.id}>{run.sweepId} · {new Date(run.updatedAt).toLocaleString()} · {run.id.slice(0,8)}</option>{/each}</select><ChevronDown size={13}/></div><div class="rank-controls"><div class="select-box"><select bind:value={strategyMetric} aria-label="Ranking metric">{#each rankMetrics as metric}<option value={metric}>{metric}</option>{/each}</select><ChevronDown size={13}/></div><button class="btn secondary" onclick={()=>submitStrategy('rank')} disabled={strategyBusy||!!activeJob}><BarChart3 size={14}/> Rank selected run</button></div>{/if}{#if historyJobs.length}<div class="label">Persisted job history · {historyJobs.length.toLocaleString()} available</div><div class="select-box"><select bind:value={selectedHistoryJobId} aria-label="Persisted validation, replay or ranking job">{#each historyJobs as job (job.id)}<option value={job.id}>{job.operation} · {job.status} · {job.sweepId} · {new Date(job.updatedAt).toLocaleString()} · {job.id.slice(0,8)}</option>{/each}</select><ChevronDown size={13}/></div>{/if}{#if selectedHistoryJob}<div class="strategy-result"><div class="result-head"><b>{selectedHistoryJob.operation} job</b><span class="job-state {selectedHistoryJob.status}">{selectedHistoryJob.status}</span></div><small>{selectedHistoryJob.sweepId} · {new Date(selectedHistoryJob.updatedAt).toLocaleString()} · {selectedHistoryJob.id}</small>{#if selectedHistoryJob.error}<pre class="job-error">{selectedHistoryJob.error}</pre>{:else if selectedHistoryJob.result}<pre>{strategyResultText(selectedHistoryJob)}</pre>{:else if selectedHistoryJob.progress}<pre>{JSON.stringify(selectedHistoryJob.progress,null,2)}</pre>{/if}</div>{/if}{#if selectedHistoryJob?.operation==='rank' && selectedHistoryJob.status==='complete'}<StrategyCandidateImport jobId={selectedHistoryJob.id}/>{/if}<div id="sweep-editor"><StrategySweepEditor {sweeps} onCreated={(created)=>{void refreshStrategy().then(()=>{strategySweepId=created.id})}}/></div><LuaPrototype sweepId={strategySweepId}/><div class="save-row"><input aria-label="Workspace name" bind:value={configName}/><button class="btn secondary" onclick={save}><Bookmark size={14}/> Save workspace</button></div></aside></div>
{#if displayRun}<section class="panel replay-results"><div class="kicker">REPLAY ANALYSIS</div><h2>Strategy results</h2><ReplayResults jobId={displayRun.id}/>{#if displayRun.operation==='run'}<SweepHeatmap jobId={displayRun.id}/>{/if}</section>{/if}
<section class="lower"><div class="panel feature"><div class="feature-icon"><Waves size={18}/></div><div><div class="kicker">BAR CONSTRUCTION</div><h3>Explore different views of price</h3><p>Stored raw ticks can build time, tick, volume and range bars. Tick, volume and range bars remain distinct, including bars with identical timestamps.</p></div><span class="soon">STORED DATA</span></div><div class="panel feature"><div class="feature-icon gold"><Layers3 size={18}/></div><div class="feature-copy"><div class="kicker">PARAMETER SWEEP</div><h3>Rank native replay output</h3><p>Run an existing native sweep, then rank its completed summary with a supported metric. No workflow runs automatically.</p></div><button class="btn secondary" onclick={()=>void refreshStrategy()} disabled={strategyLoading}><Activity size={14}/> Refresh specs</button></div></section><footer>Research workspace <span>·</span> Live engine observation and local replay · No orders from this workspace</footer></div></main>{#if toast}<div class="toast">{toast}</div>{/if}</div>
